#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <tuple>
using namespace std;

using ll = long long;

const int MAX_NODES = 7100;
const int MAX_GRID = 14;
const ll INF = 1000000000;

struct Edge {
    int u, v;
    ll flow, cap;
};

struct MaxFlow {
    int src, dst;
    vector<Edge> edges;
    vector<int> graph[MAX_NODES];
    int dist[MAX_NODES], cur[MAX_NODES];

    void clear() {
        edges.clear();
        for (int i = 0; i < MAX_NODES; ++i) graph[i].clear();
    }

    void link(int a, int b, ll capacity) {
        edges.push_back({a, b, 0, capacity});
        edges.push_back({b, a, 0, 0});
        graph[a].push_back(edges.size() - 2);
        graph[b].push_back(edges.size() - 1);
    }

    bool buildLevels() {
        memset(dist, -1, sizeof(dist));
        queue<int> q;
        q.push(src);
        dist[src] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : graph[u]) {
                Edge& e = edges[id];
                if (dist[e.v] == -1 && e.cap > e.flow) {
                    dist[e.v] = dist[u] + 1;
                    q.push(e.v);
                }
            }
        }
        return dist[dst] != -1;
    }

    ll pushFlow(int u, ll bottleneck) {
        if (u == dst || bottleneck == 0) return bottleneck;
        for (int& i = cur[u]; i < (int)graph[u].size(); ++i) {
            int id = graph[u][i];
            Edge& e = edges[id];
            if (dist[e.v] == dist[u] + 1 && e.cap > e.flow) {
                ll pushed = pushFlow(e.v, min(bottleneck, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[id ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll solve() {
        ll total = 0;
        while (buildLevels()) {
            memset(cur, 0, sizeof(cur));
            while (ll pushed = pushFlow(src, INF)) {
                total += pushed;
            }
        }
        return total;
    }
};

MaxFlow flow;
char board1[MAX_GRID][MAX_GRID], board2[MAX_GRID][MAX_GRID];
bool seen[MAX_GRID][MAX_GRID];
int timeCost[MAX_GRID][MAX_GRID];
int sizeN, timeSteps;
int finalNode[103];

int nodeID(int t, int x, int y) {
    return t * sizeN * sizeN + (x - 1) * sizeN + y;
}

void expand(int sx, int sy) {
    queue<tuple<int, int, int>> q;
    for (int i = 0; i < MAX_GRID; ++i)
        for (int j = 0; j < MAX_GRID; ++j)
            timeCost[i][j] = 111;

    timeCost[sx][sy] = 0;
    q.emplace(sx, sy, 0);
    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [x, y, d] = q.front(); q.pop();
        if (seen[x][y]) continue;
        seen[x][y] = true;
        timeCost[x][y] = d;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 1 || nx > sizeN || ny < 1 || ny > sizeN || seen[nx][ny] || board1[nx][ny] == 'Y')
                continue;
            q.emplace(nx, ny, d + 1);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> sizeN >> timeSteps;
    for (int i = 1; i <= sizeN; ++i) cin >> (board1[i] + 1);
    for (int i = 1; i <= sizeN; ++i) cin >> (board2[i] + 1);

    flow.clear();
    flow.src = 0;
    flow.dst = MAX_NODES - 2;

    int startX = 0, startY = 0;
    for (int i = 1; i <= sizeN; ++i) {
        for (int j = 1; j <= sizeN; ++j) {
            if (board1[i][j] == 'Z') {
                startX = i; startY = j;
                break;
            }
        }
    }

    for (int i = 1; i <= sizeN * sizeN; ++i)
        finalNode[i] = MAX_NODES - 3 - (sizeN * sizeN - i);

    expand(startX, startY);

    for (int i = 1; i <= sizeN; ++i) {
        for (int j = 1; j <= sizeN; ++j) {
            if (isdigit(board1[i][j]))
                flow.link(flow.src, nodeID(0, i, j), board1[i][j] - '0');
            if (isdigit(board2[i][j]))
                flow.link(finalNode[nodeID(0, i, j)], flow.dst, board2[i][j] - '0');
            flow.link(nodeID(0, i, j), finalNode[nodeID(0, i, j)], INF);
        }
    }

    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};
    for (int t = 1; t <= timeSteps; ++t) {
        for (int i = 1; i <= sizeN; ++i) {
            for (int j = 1; j <= sizeN; ++j) {
                if (board1[i][j] == 'Y' || board1[i][j] == 'Z') continue;
                for (int d = 0; d < 4; ++d) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ni >= 1 && ni <= sizeN && nj >= 1 && nj <= sizeN &&
                        board1[ni][nj] != 'Y' && board1[ni][nj] != 'Z' &&
                        timeCost[i][j] >= t && timeCost[ni][nj] >= t) {
                        flow.link(nodeID(t - 1, ni, nj), nodeID(t, i, j), INF);
                    }
                }
                flow.link(nodeID(t, i, j), finalNode[nodeID(0, i, j)], INF);
            }
        }
    }

    cout << flow.solve() << '\n';
    return 0;
}
